from pathlib import Path
p=Path(__file__).resolve().parents[1]/'src/App.jsx';s=p.read_text(encoding='utf-8')
s=s.replace('const[context,setContext]=useState(null),[clipboard,setClipboard]=useState(null);','const[context,setContext]=useState(null),[clipboard,setClipboard]=useState(null),[desktopSelection,setDesktopSelection]=useState([]);')
s=s.replace(' const appProps=win=>', ''' const desktopFiles=Object.entries(state.nodes).filter(([path])=>path.startsWith(HOME+'/Área de Trabalho/')&&path.slice((HOME+'/Área de Trabalho/').length).indexOf('/')===-1).map(([path,node])=>({path,name:path.split('/').at(-1),...node})).sort((a,b)=>(p.desktopSort==='type'?(b.type==='folder')-(a.type==='folder'):0)||a.name.localeCompare(b.name,'pt-BR'));
 const appProps=win=>''')
s=s.replace("const input=event.target.closest('input,textarea');", "const input=event.target.closest('input,textarea');const desktopItem=event.target.closest('[data-desktop-path]');")
s=s.replace("kind:launch?'app':input?'text':win?'window':'desktop',", "kind:desktopItem?'file':launch?'app':input?'text':win?'window':'desktop',path:desktopItem?.dataset.desktopPath,")
s=s.replace("if(!context)return[];const win=", """if(!context)return[];if(context.kind==='file'){const path=context.path,item=state.nodes[path];return[{label:'Abrir',action:()=>item.type==='folder'?openApp('files',{path}):openApp('editor',{path})},null,{label:'Recortar',shortcut:'Ctrl+X',action:()=>setClipboard({paths:[path],copy:false})},{label:'Copiar',shortcut:'Ctrl+C',action:()=>setClipboard({paths:[path],copy:true})},{label:'Renomear…',shortcut:'F2',action:async()=>{const name=await dialog.prompt('Renomear',path.split('/').at(-1));if(name!==null){try{store.fs.rename(path,name);}catch(error){dialog.alert(error.message);}}}},null,{label:'Mover para a Lixeira',shortcut:'Delete',danger:true,action:()=>{try{store.fs.remove(path,true);}catch(error){dialog.alert(error.message);}}}];}const win=""")
s=s.replace("document.querySelectorAll('.desktop-file').forEach(e=>e.classList.add('desktop-selected'));", "setDesktopSelection(desktopFiles.map(item=>item.path));")
s=s.replace("{label:'Organizar ícones',action:()=>notify('Ícones organizados na Área de Trabalho.')}", "{label:'Organizar por nome',action:()=>preference({desktopSort:'name'})},{label:'Organizar por tipo',action:()=>preference({desktopSort:'type'})}")
s=s.replace('className="home-shortcut"', 'className="home-shortcut" data-launch-app="files"')
s=s.replace('<span>Pasta pessoal</span></button></div>', '''<span>Pasta pessoal</span></button>{desktopFiles.map((item,index)=>{const rows=Math.max(1,Math.floor((viewport.height-160)/110));return <button key={item.path} data-desktop-path={item.path} className={'desktop-file '+(desktopSelection.includes(item.path)?'desktop-selected':'')} style={{bottom:128+index%rows*110,right:26+Math.floor(index/rows)*104}} onPointerDown={e=>e.stopPropagation()} onClick={()=>setDesktopSelection([item.path])} onDoubleClick={()=>item.type==='folder'?openApp('files',{path:item.path}):openApp('editor',{path:item.path})}><img src={item.type==='folder'?'assets/places/folder.png':'assets/symbolic/text-x-generic.svg'} alt=""/><span>{item.name}</span></button>;})}</div>''')
s=s.replace('Math.max(300,Math.min(viewport.width-x,w+dx))', "Math.max(d.win.app==='files'?520:d.win.app==='settings'?560:300,Math.min(viewport.width-x,w+dx))")
s=s.replace('Math.min(x+w-300,x+dx)', "Math.min(x+w-(d.win.app==='files'?520:d.win.app==='settings'?560:300),x+dx)")
p.write_text(s,encoding='utf-8')
